import { type JSX } from 'solid-js'

import { claimSlot, scope } from '@polymorph/solid'
import styles from '@polymorph/recipes/exceptions/third-party.module.css'

export interface ThirdPartyProps {
  children?: JSX.Element
  /**
   * The package the hosted component comes from, as it is imported: `leaflet`, `@tiptap/react`.
   */
  library: string
  /**
   * Why the vocabulary was not enough, for a reviewer reading the inventory.
   */
  reason: string
}

/** Rung 4 of the exception ladder (`docs/rules.md`): the declared boundary around another library's component, such as a map, a rich-text editor or a data grid. */
export default function ThirdParty(given: ThirdPartyProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    return (
      <div class={styles.thirdParty} data-third-party={props.library} data-reason={props.reason}>
        {props.children}
      </div>
    )
  })
}
